INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(43911, 'Ezra 8:32', 'Ezra', 8, 32, 'کله چې اورشلیم ته ورسېدلو، درې ورځې مونږ هلته دمه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_32.mp3', '', 1761754199, 1761754199),
(43912, 'Ezra 8:33', 'Ezra', 8, 33, 'په څلورمه ورځ د خپل خدای کور ته لاړو، سپین زر، سره زر او لوښي مو وتلل او هغه مو مریموت کاهن ته چې د اوریا زوی ؤ، ورکړل. العازار د فینحاس زوی او دوه لاویان یعنې د یشوع زوی یوزاباد او د بنوي زوی نوعدیه هم د مریموت سره وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_33.mp3', '', 1761754199, 1761754199),
(43913, 'Ezra 8:34', 'Ezra', 8, 34, 'ټول شیان وشمېرل شول او وتلل شول او په هماغه وخت کې د هر شي وزن ولیکل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_34.mp3', '', 1761754199, 1761754199),
(43914, 'Ezra 8:35', 'Ezra', 8, 35, 'هغو خلکو چې د جلاوطنۍ څخه راستانه شوي وو د اسراییلو خدای ته سوځېدونکې نذرانې قرباني کړې. هغوی دولس غویان د ټولو اسراییلیانو دپاره او همدارنګه شپږ نوي پسونه او اووه اویا وري نذرانه کړل. هغوی دولس سېرلي هم د ګناه څخه د خپلو ځانونو د پاکولو دپاره نذرانه کړل. دا ټول حیوانات څښتن ته د سوځېدونکې قربانۍ په توګه وړاندې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_35.mp3', '', 1761754199, 1761754199),
(43915, 'Ezra 8:36', 'Ezra', 8, 36, 'همدارنګه هغوی هغه سند چې پاچا ورته ورکړی ؤ، واخیست او هغه یې د فرات د سیند د لوېدیځې سیمې والیانو او مامورینو ته ورکړ او هغوی بیا د خلکو او د خدای د کور څخه ملاتړ او مرسته وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_36.mp3', '', 1761754199, 1761754199),
(43916, 'Proverbs 1:1', 'Proverbs', 1, 1, 'دا د اسراییلو د پاچا او د داود د زوی سلیمان متلونه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_1.mp3', '', 1761754199, 1761754199),
(43917, 'Proverbs 1:2', 'Proverbs', 1, 2, 'د دې متلونو مقصد دا دی چې خلک په حکمت او نصیحت پوره پوه شي او د عقلمندۍ خبرې زده کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_2.mp3', '', 1761754199, 1761754199),
(43918, 'Proverbs 1:3', 'Proverbs', 1, 3, 'ترڅو نصیحت ومني چې هوښیار شي او خپل ژوند په انصاف، عدالت او برابرۍ تېر کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_3.mp3', '', 1761754199, 1761754199),
(43919, 'Proverbs 1:4', 'Proverbs', 1, 4, 'چې ساده خلکو ته پوهه ورکوي او ځوانانو ته علم او لیاقت وربخښي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_4.mp3', '', 1761754199, 1761754199),
(43920, 'Proverbs 1:5', 'Proverbs', 1, 5, 'نو هوښیاران دې واوري او خپل تعلیم دې زیات کړي او عقلمندان دې له نورو ښې مشورې واخلي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_5.mp3', '', 1761754199, 1761754199),
(43921, 'Proverbs 1:6', 'Proverbs', 1, 6, 'د دې دپاره چې د متلونو او نصیحتونو په اهمیت پوه شي او د حکمت د خاوندانو خبرې او رازونه هم وپېژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_6.mp3', '', 1761754199, 1761754199),
(43922, 'Proverbs 1:7', 'Proverbs', 1, 7, 'له څښتن څخه وېره د علم او پوهې شروع ده خو جاهلان حکمت او نصیحت ته په سپکه سترګه ګوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_7.mp3', '', 1761754199, 1761754199),
(43923, 'Proverbs 1:8', 'Proverbs', 1, 8, 'ای زما زویه! د خپل پلار نصیحت ته غوږ ونیسه او د خپلې مور روزنه له پامه مه غورځوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_8.mp3', '', 1761754199, 1761754199),
(43924, 'Proverbs 1:9', 'Proverbs', 1, 9, 'ځکه دا ستا دپاره د افتخار شمله ده او ستا د غاړې دپاره ښکلی هار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_9.mp3', '', 1761754199, 1761754199),
(43925, 'Proverbs 1:10', 'Proverbs', 1, 10, 'نو ای زما زویه! که ګناهکاران تا لمسوي نو د هغوی خبرو ته غوږ مه نیسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_10.mp3', '', 1761754199, 1761754199),
(43926, 'Proverbs 1:11', 'Proverbs', 1, 11, 'که هغوی تاته ووایي: «زمونږ سره راځه چې د چا د وینو د تویولو دپاره کمین ونیسو او په یو بې‌ګناه انسان ناحقه یرغل وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_11.mp3', '', 1761754199, 1761754199),
(43927, 'Proverbs 1:12', 'Proverbs', 1, 12, 'راځه چې هغوی د قبر په څېر ژوندي تېر کړو لکه هغه خلک چې روغ رمټ د مرګ کندې ته ښکته کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_12.mp3', '', 1761754199, 1761754199),
(43928, 'Proverbs 1:13', 'Proverbs', 1, 13, 'مونږ به هر ډول قیمتي مال دولت تر‌لاسه کړو او خپل کورونه به د لوټ شوې شتمنۍ نه ډک کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_13.mp3', '', 1761754199, 1761754199),
(43929, 'Proverbs 1:14', 'Proverbs', 1, 14, 'راځه، مونږ سره مل شه او لوټ شوی مال به په خپل منځ کې ووېشو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_14.mp3', '', 1761754199, 1761754199),
(43930, 'Proverbs 1:15', 'Proverbs', 1, 15, 'نو ای زما زویه! د هغوی سره په لاره مه ځه او د هغوی په پل قدم مه ږده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_15.mp3', '', 1761754199, 1761754199),
(43931, 'Proverbs 1:16', 'Proverbs', 1, 16, 'ځکه د هغوی پښې د بدۍ او زیان په لور منډې وهي او د وینو تویولو طرف ته په بیړه روان دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_16.mp3', '', 1761754199, 1761754199),
(43932, 'Proverbs 1:17', 'Proverbs', 1, 17, 'نو د یو وزر لرونکي په مخکې جال غوړول بې‌ګټې کار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_17.mp3', '', 1761754199, 1761754199),
(43933, 'Proverbs 1:18', 'Proverbs', 1, 18, 'داسې خلک چې نورو ته په کمین کې ناست وي نو خپله وینه تویوي او هغوی چې په نورو یرغل کوي نو خپل ځانونه په دام کې نښلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_18.mp3', '', 1761754199, 1761754199),
(43934, 'Proverbs 1:19', 'Proverbs', 1, 19, 'نو بیا ټول ټګان چې د داسې لارو ناروا ګټه تر‌لاسه کوي نو په داسې ګټې سره خپل ژوند له لاسه ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_19.mp3', '', 1761754199, 1761754199),
(43935, 'Proverbs 1:20', 'Proverbs', 1, 20, 'حکمت په لارو کوڅو کې چیغې وهي او په چوکونو کې په لوړ اواز نارې وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_20.mp3', '', 1761754199, 1761754199),
(43936, 'Proverbs 1:21', 'Proverbs', 1, 21, 'د ګڼې ګوني په ځایونو کې خپل غږ پورته کوي او د ښار د دروازو دننه خپله وینا کوي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_21.mp3', '', 1761754199, 1761754199),
(43937, 'Proverbs 1:22', 'Proverbs', 1, 22, '«ای ساده خلکو، ترڅو به تاسو له ناپوهۍ سره مینه لرئ؟ ترڅو به ملنډې وهونکي له ملنډو نه خوند اخلي او کم‌عقل خلک به له علم نه کرکه کوي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_22.mp3', '', 1761754199, 1761754199),
(43938, 'Proverbs 1:23', 'Proverbs', 1, 23, 'ماته مخ راواړوئ او زما سختې خبرې واورئ نو زه به د خپل زړه دروازه تاسو ته بېرته کړم او خپل کلام به تاسو ته ښکاره کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_23.mp3', '', 1761754199, 1761754199),
(43939, 'Proverbs 1:24', 'Proverbs', 1, 24, 'ما تاسو ته غږ وکړ خو غوږونه مو بند کړي وو. کله چې مې لاس در وغزولو نو سترګې مو ورباندې پټې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_24.mp3', '', 1761754199, 1761754199),
(43940, 'Proverbs 1:25', 'Proverbs', 1, 25, 'زما ټولې لارښوونې مو له پام نه وغورځولې او زما سختې خبرې مو ونه منلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_25.mp3', '', 1761754199, 1761754199),
(43941, 'Proverbs 1:26', 'Proverbs', 1, 26, 'کله چې په تاسو لوی مصیبت راشي زه به په تاسو پورې وخاندم او کله چې په تاسو لویه بلا راشي تاسو پورې به ملنډې ووهم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_26.mp3', '', 1761754199, 1761754199),
(43942, 'Proverbs 1:27', 'Proverbs', 1, 27, 'کله چې په تاسو لویه بلا د توفان په شان راشي کله چې لوی مصیبت لکه د سختې سیلۍ په څېر په تاسې نازل شي او کله چې سختي او تکلیف په تاسو راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_27.mp3', '', 1761754199, 1761754199),
(43943, 'Proverbs 1:28', 'Proverbs', 1, 28, 'نو بیا به هغوی ماته چیغې وهي خو زه به ځواب نه ورکوم او په سختۍ به ما لټوي خو پیدا به مې نه کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_28.mp3', '', 1761754199, 1761754199),
(43944, 'Proverbs 1:29', 'Proverbs', 1, 29, 'ځکه چې هغوی له علم نه کرکه وکړه او له څښتن څخه یې وېره غوره نه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_29.mp3', '', 1761754199, 1761754199),
(43945, 'Proverbs 1:30', 'Proverbs', 1, 30, 'هغوی زما لارښوونه ونه منله او زما ټولو سختو خبرو ته یې په سپکه وکتل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_30.mp3', '', 1761754199, 1761754199),
(43946, 'Proverbs 1:31', 'Proverbs', 1, 31, 'نو بیا به د خپلې کړنې مېوه وخوري او د خپلو دسیسو په ترخه مېوه به ماړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_31.mp3', '', 1761754199, 1761754199),
(43947, 'Proverbs 1:32', 'Proverbs', 1, 32, 'نو د ساده خلکو سرکښي به د دوی د مرګ سبب شي او د کم‌عقلانو بې‌پروایي به دوی تباه کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_32.mp3', '', 1761754199, 1761754199),
(43948, 'Proverbs 1:33', 'Proverbs', 1, 33, 'خو هرڅوک چې زما واوري هغه به په امن کې ژوند کوي او له زیان څخه به وېره ونه لري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs1_verse_33.mp3', '', 1761754199, 1761754199),
(43949, 'Joshua 2:1', 'Joshua', 2, 1, 'بیا د نون زوی یوشع د شطیم د کمپ څخه په پټه دوه جاسوسان د دې حکم سره ولېږل چې لاړ شي او د کنعان د خاورې او په ځانګړې توګه د اریحا د ښار په هکله معلومات واخلي. کله چې هغوی ښار ته ورسېدل، نو هغوی لاړل چې د راحاب په نوم د یوې بدلمنې په کور کې شپه تېره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_1.mp3', '', 1761754199, 1761754199),
(43950, 'Joshua 2:2', 'Joshua', 2, 2, 'د اریحا پاچا خبر شو چې نن شپه ځینې اسراییلیان راغلي دي چې په دې خاوره کې جاسوسي وکړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_2.mp3', '', 1761754199, 1761754199),
(43951, 'Joshua 2:3', 'Joshua', 2, 3, 'نو هغه راحاب ته دا پیغام ورولېږه: «هغه خلک چې ستا کور ته راغلي دي غواړي چې د ټولې خاورې جاسوسي وکړي! هغوی دباندې راوباسه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_3.mp3', '', 1761754199, 1761754199),
(43952, 'Joshua 2:7', 'Joshua', 2, 7, 'د پاچا کسان د ښار څخه لاړل او بیا دروازه بنده شوه. هغوی د اسراییلي جاسوسانو د لټولو په خاطر تر هغه ځای پورې لاړل په کوم ځای کې چې خلک به د اردن د سیند څخه تېرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_7.mp3', '', 1761754199, 1761754199),
(43953, 'Joshua 2:8', 'Joshua', 2, 8, 'د شپې له خوا مخکې له دې چې جاسوسان ویده شي، راحاب بام ته وروختله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_8.mp3', '', 1761754199, 1761754199),
(43954, 'Joshua 2:9', 'Joshua', 2, 9, 'او هغوی ته یې وویل: «زه پوهېږم چې څښتن دا ځمکه تاسو ته درکړې ده او هرڅوک په دې هېواد کې ستاسو څخه سخت وېریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_9.mp3', '', 1761754199, 1761754199),
(43955, 'Joshua 2:10', 'Joshua', 2, 10, 'مونږ اورېدلي دي کله چې تاسو د مصر څخه راوتلئ، نو څښتن څنګه ستاسو په مخکې د سرې بحیرې اوبه وچې کړې. او مونږ خبر یو چې تاسو څنګه د اموریانو دوه پاچاهان یعنې سیحون او عوج د اردن د سیند په ختیځ کې له منځه یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_10.mp3', '', 1761754199, 1761754199),
(43956, 'Joshua 2:11', 'Joshua', 2, 11, 'څنګه چې مونږ د دې څخه خبر شو، نو ووېرېدلو او خپل جرات مو له لاسه ورکړ، ځکه چې ستاسو څښتن خدای د ځمکې او اسمان خدای دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_11.mp3', '', 1761754199, 1761754199),
(43957, 'Joshua 2:12', 'Joshua', 2, 12, 'نو اوس ماته د هغه په نوم قسم وخورئ چې تاسو به زما د کورنۍ سره داسې د مهربانۍ څخه ډک چلند کوئ، لکه څنګه چې ما ستاسو سره کړې دی او ماته یوه داسې نښه راکړئ چې په تاسو باندې اعتبار وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_12.mp3', '', 1761754199, 1761754199),
(43958, 'Joshua 2:13', 'Joshua', 2, 13, 'زما سره وعده وکړئ چې زما مور او پلار، زما خویندې او ورونه به د هغوی د ټولې کورنۍ سره ژغورئ! مونږ مه پرېږدئ چې مړه شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_13.mp3', '', 1761754199, 1761754199),
(43959, 'Joshua 2:14', 'Joshua', 2, 14, 'هغو سړیو هغې ته وویل: «که چېرې مونږ په خپلې خبرې باندې عمل ونه کړ، نو خدای دې زمونږ ژوند واخلي! که چېرې ته چاته ونه وایې چې مونږ څه کوو، مونږ ستا سره وعده کوو کله چې څښتن مونږ ته دا ځمکه راکړي، مونږ به ستا سره ښه چلند وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_14.mp3', '', 1761754199, 1761754199),
(43960, 'Joshua 2:15', 'Joshua', 2, 15, 'نو راحاب هغوی په یوې رسۍ باندې د کړکۍ په لاره ښکته کړل، ځکه چې په کوم کور کې چې هغه اوسېدله، هغه د ښار په دېوال باندې ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_15.mp3', '', 1761754199, 1761754199),
(43961, 'Joshua 2:16', 'Joshua', 2, 16, 'راحاب هغوی ته وویل: «غونډیو ته لاړ شئ، که نه، نو د پاچا کسان به تاسو راپیدا کړي. درې ورځې هلته ځانونه پټ کړئ، ترڅو هغوی بېرته راشي، له هغې وروسته کولای شئ چې په خپله لاره لاړ شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_16.mp3', '', 1761754199, 1761754199),
(43962, 'Joshua 2:17', 'Joshua', 2, 17, 'سړیو هغې ته وویل: «په کومه وعده باندې چې تا مونږ مجبور کړو په هغې باندې به عمل کوو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_17.mp3', '', 1761754199, 1761754199),
(43963, 'Joshua 2:18', 'Joshua', 2, 18, 'کله چې مونږ ستاسو په خاوره باندې حمله وکړه، دا سور مزی په هغې کړکۍ باندې وتړه چې تا ورباندې راښکته کړو. خپل پلار، مور، ورونه او د خپل پلار ټوله کورنۍ په خپل کور کې سره راټول کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_18.mp3', '', 1761754199, 1761754199),
(43964, 'Joshua 2:19', 'Joshua', 2, 19, 'که چېرې څوک ستا د کور څخه ووځي، نو د هغه خون به د هغه په خپله غاړه وي او مسوولیت به یې زمونږ په غاړه نه وي. خو که چېرې ستا په کور کې چاته زیان ورسیږي، بیا به مسوولیت زمونږ په غاړه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_19.mp3', '', 1761754199, 1761754199),
(43965, 'Joshua 2:20', 'Joshua', 2, 20, 'خو که چېرې چاته ووایې چې مونږ څه کوو، نو بیا به مونږ مجبور نه یو په هغې وعدې باندې ټینګ پاتې شو چې تا په مونږ باندې کړې وه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_20.mp3', '', 1761754199, 1761754199),
(43966, 'Joshua 2:21', 'Joshua', 2, 21, 'راحاب دا خبره ومنله او هغوی یې رخصت کړل. کله چې هغوی لاړل، هغې په کړکۍ باندې سور مزی وتړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_21.mp3', '', 1761754199, 1761754199),
(43967, 'Joshua 2:22', 'Joshua', 2, 22, 'هغه جاسوسان غونډیو ته لاړل او پټ شول. د پاچا کسانو درې ورځې د هغې سیمې ټولې لارې ولټولې، خو هغوی یې پیدا نه کړل، نو هغوی بېرته اریحا ته راستانه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_22.mp3', '', 1761754199, 1761754199),
(43968, 'Joshua 2:23', 'Joshua', 2, 23, 'بیا هغه دوه جاسوسان د غونډیو څخه راښکته شول، د اردن د سیند څخه تېر شول او بېرته یوشع ته ورغلل. هرڅه چې په هغوی باندې تېر شوي وو هغه ته یې بیان کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_23.mp3', '', 1761754199, 1761754199),
(43969, 'Joshua 2:24', 'Joshua', 2, 24, 'هغوی یوشع ته وویل: «مونږ باور لرو چې څښتن مونږ ته هغه ټول هېواد راکړی دی. د هغه ځای ټول خلک زمونږ څخه سخت وېریږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua2_verse_24.mp3', '', 1761754199, 1761754199),
(43970, 'Hosea 6:1', 'Hosea', 6, 1, 'خلک وایي: «راځئ چې د څښتن خواته راوګرځو! هغه مونږ ټوټې ټوټې کړي یو، خو اوس به مونږ روغ کړي. هغه مونږ زخمي کړي یو، خو اوس به زمونږ په زخمونو باندې پټۍ کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_1.mp3', '', 1761754199, 1761754199),
(43971, 'Hosea 6:2', 'Hosea', 6, 2, 'په ډېر کم وخت کې به هغه مونږ ته نوی ژوند راکړي او مونږ به راپورته کړي، ترڅو د هغه په حضور کې ژوند وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_2.mp3', '', 1761754199, 1761754199),
(43972, 'Hosea 6:3', 'Hosea', 6, 3, 'راځئ کوښښ وکړو چې هغه وپېژنو. لکه څنګه چې دا یقیني ده چې لمر راخېژي، نو هغه به هم لکه د باران په شان مونږ ته راشي، لکه څنګه چې د پسرلي باران ځمکه اوبه کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_3.mp3', '', 1761754199, 1761754199),
(43973, 'Hosea 6:4', 'Hosea', 6, 4, 'خو څښتن وایي: «ای د اسراییلو او یهودا خلکو، زه ستاسو سره څه وکړم؟ تاسو چې ما سره کومه مینه کوئ، هغه د سهار د لړو او دوپ په شان ډېر زر ورکیږي او هغه د هغې پرخې په شان ده چې سهار وختي له منځه ځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_4.mp3', '', 1761754199, 1761754199),
(43974, 'Hosea 6:5', 'Hosea', 6, 5, 'له همدې امله ما خپل پیغمبران درلېږلي دي چې تاسو ټوټې ټوټې کړي، ترڅو زما پیغام تاسو ته ستاسو د تباهۍ دپاره درورسوي. زما قضاوت به لکه د برېښنا په شان راځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_5.mp3', '', 1761754199, 1761754199),
(43975, 'Hosea 6:6', 'Hosea', 6, 6, 'زه ستاسو نه وفاداري غواړم، نه قرباني. زه ستاسو نه سوځېدونکې نذرانې نه غواړم، بلکې زه دا غواړم چې خلک ما وپېژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_6.mp3', '', 1761754199, 1761754199),
(43976, 'Hosea 6:7', 'Hosea', 6, 7, 'خو هغوی لکه د آدم په شان زما لوظ مات کړ او هلته هغوی زما سره بې‌وفایي وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_7.mp3', '', 1761754199, 1761754199),
(43977, 'Hosea 6:8', 'Hosea', 6, 8, 'جلعاد هغه ښار دی چې د بدکاره خلکو څخه ډک دی او هرې خواته په کې وینه پرته ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_8.mp3', '', 1761754199, 1761754199),
(43978, 'Hosea 6:9', 'Hosea', 6, 9, 'کاهنان د هغو لوټمارانو په شان دي چې کوم چاته په کمین کې ناست وي. حتی هغوی د شکیم د پناه اخیستلو ښار په لاره کې قتلونه کوي. هغوی دا ټول بد کارونه په قصدي توګه کوي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_9.mp3', '', 1761754199, 1761754199),
(43979, 'Hosea 6:10', 'Hosea', 6, 10, 'ما په اسراییلو کې ډېر هیبتناکه کارونه لیدلي دي. زما خلکو بتانو ته په عبادت کولو سره خپل ځانونه لکه د فاحشو په شان ناپاکه کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_10.mp3', '', 1761754199, 1761754199),
(43980, 'Hosea 6:11', 'Hosea', 6, 11, 'خو ای د یهودا خلکو، ما تاسو ته هم د سزا ورکولو دپاره وخت ټاکلی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea6_verse_11.mp3', '', 1761754199, 1761754199),
(43981, 'Leviticus 16:1', 'Leviticus', 16, 1, 'د هارون د دوو زامنو د مړینې څخه وروسته چې څښتن ته ورنژدې شول او مړه شول، څښتن د موسی سره خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_1.mp3', '', 1761754199, 1761754199),
(43982, 'Leviticus 16:2', 'Leviticus', 16, 2, 'هغه وویل: «خپل ورور هارون ته ووایه چې یوازې په یو مناسب وخت کې دې ډېر سپېڅلي ځای ته چې د پردې شاته دی ورننوځي، ځکه دا هغه ځای دی چې زه په کې په ورېځو کې د لوظ د صندوق د سرپوښ دپاسه راښکاره کېږم. که هغه سرغړونه وکړي، نو وبه وژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_2.mp3', '', 1761754199, 1761754199),
(43983, 'Leviticus 16:3', 'Leviticus', 16, 3, 'کله چې هارون د ګناه د نذرانې دپاره یو خوسی او د سوځېدونکې نذرانې دپاره یو پسه راوړي، بیا هغه کولای شي چې ډېر سپېڅلي ځای ته ورننوځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_3.mp3', '', 1761754199, 1761754199),
(43984, 'Leviticus 16:4', 'Leviticus', 16, 4, 'بیا څښتن دا لارښوونې وکړې: «مخکې له دې چې هارون ډېر سپېڅلي ځای ته ننوځي، هغه باید غسل وکړي او د کاهنتوب دغه سپېڅلي کالي دې واغوندي: د کتان کمیس، نېکرونه، پټۍ او لونګۍ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_4.mp3', '', 1761754199, 1761754199),
(43985, 'Leviticus 16:5', 'Leviticus', 16, 5, 'د اسراییلو قوم دې هارون ته دوه سېرلي د ګناه د نذرانې دپاره او یو پسه د سوځېدونکې نذرانې دپاره ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_5.mp3', '', 1761754199, 1761754199),
(43986, 'Leviticus 16:6', 'Leviticus', 16, 6, 'هارون دې یو غویی د خپلې ګناه د نذرانې دپاره وړاندې کړي چې د خپل ځان او خپلې کورنۍ دپاره کفاره ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_6.mp3', '', 1761754199, 1761754199),
(43987, 'Leviticus 16:7', 'Leviticus', 16, 7, 'بیا دې هغه دوه سېرلي واخلي او د سپېڅلې خېمې د دروازې په خوله کې دې د څښتن په حضور کې وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_7.mp3', '', 1761754199, 1761754199),
(43988, 'Leviticus 16:8', 'Leviticus', 16, 8, 'هغه دې د دوو سېرلیو دپاره پچه واچوي او د دوه تیږو څخه دې کار واخلي، په یوې باندې دې د څښتن دپاره نښه وکړي او په بلې باندې دې د عزازیل دپاره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_8.mp3', '', 1761754199, 1761754199),
(43989, 'Leviticus 16:9', 'Leviticus', 16, 9, 'هارون به هغه سېرلی چې د څښتن دپاره د پچې په وسیله غوره شوی وي، د ګناه د نذرانې په توګه قرباني کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_9.mp3', '', 1761754199, 1761754199),
(43990, 'Leviticus 16:10', 'Leviticus', 16, 10, 'کوم سېرلی چې د عزازیل دپاره غوره شوی ؤ هغه به څښتن ته ژوندی وړاندې شي او په دښته کې به عزازیل ته ورولېږل شي، د دې په خاطر چې د قوم د ګناهونو دپاره کفاره ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_10.mp3', '', 1761754199, 1761754199),
(43991, 'Leviticus 16:11', 'Leviticus', 16, 11, 'کله چې هارون یو غویی د خپلې ګناه د نذرانې دپاره حلال کړي چې د خپل ځان او خپلې کورنۍ دپاره کفاره ادا کړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_11.mp3', '', 1761754199, 1761754199),
(43992, 'Leviticus 16:12', 'Leviticus', 16, 12, 'نو هغه به د قربانۍ د ځای څخه د اور یو لوښی چې د لګول شویو سکارو څخه ډک وي او دوه موټي ښه میده شوې خوشبویي راواخلي او هغه دې ډېر سپېڅلي ځای ته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_12.mp3', '', 1761754199, 1761754199),
(43993, 'Leviticus 16:13', 'Leviticus', 16, 13, 'هغه به هلته د څښتن په حضور کې خوشبویي په اور باندې واچوي او د خوشبویۍ لوګی به د لوظ د صندوق سرپوښ پټ کړي، ترڅو هارون هغه ونه ویني او مړ نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_13.mp3', '', 1761754199, 1761754199),
(43994, 'Leviticus 16:14', 'Leviticus', 16, 14, 'د غویي لږه وینه به واخلي او په خپلې ګوتې باندې به یې د سرپوښ مخکینۍ برخې ته وشیندي او بیا به د هغې څخه لږه د لوظ د صندوق مخې ته اووه ځلې وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_14.mp3', '', 1761754199, 1761754199),
(43995, 'Leviticus 16:15', 'Leviticus', 16, 15, 'بیا به هارون د ګناه د نذرانې سېرلی د قوم په خاطر حلال کړي او د هغه وینه به ډېر سپېڅلي ځای ته یوسي او هماغسې کار به ورسره وکړي چې د غویي په وینه باندې یې کړی ؤ. هغه به د لوظ د صندوق په سرپوښ او د صندوق مخې ته وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_15.mp3', '', 1761754199, 1761754199),
(43996, 'Leviticus 16:16', 'Leviticus', 16, 16, 'په دې ډول به هغه د پاکولو مراسم سرته ورسوي چې ډېر سپېڅلی ځای د اسراییلو د قوم د ناپاکۍ او د هغوی د ټولو ګناهونو څخه پاک کړي. هغه دې دا کار د سپېڅلې خېمې دپاره هم وکړي، ځکه چې هغه د کمپ په منځ کې ولاړه ده او کمپ په مذهبي لحاظ ناپاک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_16.mp3', '', 1761754199, 1761754199),
(43997, 'Leviticus 16:17', 'Leviticus', 16, 17, 'له هغه وخت څخه چې هارون ډېر سپېڅلي ځای ته د کفارې د ادا کولو دپاره ننوځي، د هغه د راوتلو پورې باید هېڅوک په خېمه کې نه وي. کله چې هغه د خپل ځان، خپلې کورنۍ او ټول قوم دپاره کفاره ادا کوي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_17.mp3', '', 1761754199, 1761754199),
(43998, 'Leviticus 16:18', 'Leviticus', 16, 18, 'نو باید بیا د نذرانو د سوځولو دپاره د قربانۍ ځای ته لاړ شي او هغه پاک کړي. هغه باید د غویي او سېرلي لږه وینه واخلي او د قربانۍ د ځای په ښکرونو باندې دې وسولوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_18.mp3', '', 1761754199, 1761754199),
(43999, 'Leviticus 16:19', 'Leviticus', 16, 19, 'هغه باید په خپله ګوته لږه وینه واخلي او د قربانۍ په ځای باندې دې اووه ځلې وشیندي. په دې ډول دې هغه د اسراییلو قوم د ناپاکۍ څخه پاک او سپېڅلې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_19.mp3', '', 1761754199, 1761754199),
(44000, 'Leviticus 16:20', 'Leviticus', 16, 20, 'کله چې هارون د ډېر سپېڅلي ځای، د سپېڅلې خېمې پاتې برخې او د قربانۍ د ځای د پاکولو مراسم سرته ورسوي، هغه به هغه ژوندی سېرلی څښتن ته وړاندې کوي چې د عزازیل دپاره غوره شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_20.mp3', '', 1761754199, 1761754199),
(44001, 'Leviticus 16:21', 'Leviticus', 16, 21, 'هغه دې دواړه لاسونه د ژوندي سېرلي په سر باندې کېږدي او په هغه باندې دې د اسراییلو د قوم د ټولو بدکاریو، ګناهونو او سرکښیو اقرار وکړي او هغه دې د سېرلی په سر باندې واچوي. هغه به دا سېرلی لېرې دښتې ته ولېږي او یو داسې سړي ته دې وسپاري چې د دې کار دپاره ټاکل شوی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_21.mp3', '', 1761754199, 1761754199),
(44002, 'Leviticus 16:22', 'Leviticus', 16, 22, 'کله چې هغه سړی هغه سېرلی په دښته کې خوشې کړي، نو هغه سېرلی به د هغوی ټول ګناهونه د خپل ځان سره یو شاړ ځای ته یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_22.mp3', '', 1761754199, 1761754199),
(44003, 'Leviticus 16:23', 'Leviticus', 16, 23, 'بیا دې هارون سپېڅلې خېمې ته ورننوځي او د کتان هغه کالي چې ډېر سپېڅلي ځای ته د ورننوتلو څخه مخکې یې اغوستی ؤ، وباسي او هلته دې پرېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_23.mp3', '', 1761754199, 1761754199),
(44004, 'Leviticus 16:24', 'Leviticus', 16, 24, 'هغه به په یو سپېڅلي ځای کې غسل وکړي او خپل عادي کالي به واغوندي. بیا به هغه دباندې راووځي او یوه سوځېدونکې نذرانه به د ځان او یوه د قوم دپاره قرباني کړي، د دې په خاطر چې د خپل ځان او د هغوی دپاره کفاره ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_24.mp3', '', 1761754199, 1761754199),
(44005, 'Leviticus 16:25', 'Leviticus', 16, 25, 'همدارنګه هغه به د قربانۍ په ځای باندې د حیوان وازګه چې د ګناه د نذرانې دپاره ده، وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_25.mp3', '', 1761754199, 1761754199),
(44006, 'Leviticus 16:26', 'Leviticus', 16, 26, 'هغه سړی چې سېرلی یې په دښته کې عزازیل ته ورپرېښود، باید کمپ ته د بېرته راتګ څخه مخکې خپل کالي ووینځي او غسل دې وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_26.mp3', '', 1761754199, 1761754199),
(44007, 'Leviticus 16:27', 'Leviticus', 16, 27, 'هغه غویی او سېرلی چې د ګناه د نذرانو دپاره ورڅخه کار واخیستل شو او د هغو وینه د کفارې د ادا کولو دپاره ډېر سپېڅلي ځای ته راوړل شوه، باید د کمپ څخه دباندې یووړل شي. د هغو پوستکي، غوښه او خوشایي دې وسوځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_27.mp3', '', 1761754199, 1761754199),
(44008, 'Leviticus 16:28', 'Leviticus', 16, 28, 'کوم سړی چې هغه سوځوي باید خپل کالي ووینځي او غسل دې وکړي، له هغې وروسته هغه کمپ ته ننوتلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_28.mp3', '', 1761754199, 1761754199),
(44009, 'Leviticus 16:29', 'Leviticus', 16, 29, 'په لاندېنیو مقرراتو باندې دې د تل دپاره عمل وشي. د اوومې میاشتې په لسمه ورځ تاسو ټول اسراییلیان او هغه پردي خلک چې ستاسو په منځ کې اوسیږي، باید روژه ونیسئ او هېڅ کار باید ونه کړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_29.mp3', '', 1761754199, 1761754199),
(44010, 'Leviticus 16:30', 'Leviticus', 16, 30, 'ځکه چې په دې ورځ به ستاسو د پاکولو دپاره کفاره ادا شي. بیا به تاسو د څښتن په حضور کې د خپلو ټولو ګناهونو څخه پاک شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus16_verse_30.mp3', '', 1761754199, 1761754199);